return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Gå til Plugin-søgning','Activate %s' => 'Aktiver %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> kræver, at <strong>%2$s</strong> er installeret og aktiveret. <a href="%4$s">%3$s</a>','Enter your code here' => 'Indtast din kode her','Add %s' => 'Tilføj %s','Remove' => 'Fjerne','Order number and receipt will be sent to this email address.' => 'Ordrenummer og kvittering sendes til denne e-mailadresse.','Apartment, unit, building, floor, etc.' => 'Lejlighed, enhed, bygning, etage osv.','Shipping phone' => 'Telefon til forsendelse','Only used for shipping-related questions.' => 'Bruges kun til forsendelsesrelaterede spørgsmål.','Single step' => 'Et enkelt trin','Click to go to the order summary' => 'Klik for at gå til ordreoversigten','Cart total:' => 'Samlet vogn:','Proceed to %s' => 'Fortsæt til %s','Proceed to contact' => 'Fortsæt med at kontakte','Proceed to shipping' => 'Fortsæt til forsendelse','Proceed to billing' => 'Fortsæt til fakturering','Proceed to payment' => 'Fortsæt til betaling','Shipping method' => 'Forsendelsesmetode','Additional notes' => 'Yderligere noter','Payment method' => 'Betalingsmetode','Step %1$s of %2$s' => 'Trin %1$s af %2$s','Change: %s' => 'Ændring: %s','Not selected yet.' => 'Ikke valgt endnu.','Same as shipping address' => 'Samme som leveringsadresse','Same as billing address' => 'Samme som faktureringsadresse','Order summary' => 'Oversigt over ordrer','Edit cart' => 'Rediger indkøbsvogn','Did you mean %s?' => 'Mente du %s?','Change email address to: {suggestion-value}' => 'Skift e-mailadresse til: {forslag-værdi}.','This is a required field.' => 'Dette er et obligatorisk felt.','This is not a valid email address.' => 'Dette er ikke en gyldig e-mailadresse.','This field does not match the related field value.' => 'Dette felt stemmer ikke overens med den relaterede feltværdi.','The CPF number "{cpf_number}" is invalid.' => 'CPF-nummeret "{cpf_number}" er ugyldigt.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ-nummeret "{cnpj_number}" er ugyldigt.','(Required)' => '(Påkrævet)','Checkout Header - Desktop' => 'Overskrift til kassen - Desktop','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Vis widgets på checkout-overskriften til store skærme. Vises kun, hvis man bruger plugin\'ets checkout-header.','Checkout Header - Mobile' => 'Overskrift til kassen - mobil','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Vis widgets under checkout-overskriften for mobile enheder. Vises kun, hvis du bruger plugin\'ets checkout-header.','Checkout Sidebar' => 'Kasse-sidebjælke','Display widgets on the checkout sidebar after the order summary.' => 'Vis widgets på checkout-sidepanelet efter ordreoversigten.','Checkout Order Summary' => 'Oversigt over ordre ved kassen','Display widgets inside the order summary at the checkout page.' => 'Vis widgets i ordreoversigten på betalingssiden.','Checkout Below Place Order' => 'Gå til kassen nedenfor Bestil','Display widgets below the place order button at the checkout page.' => 'Vis widgets under bestillingsknappen på betalingssiden.','Checkout Footer' => 'Checkout-sidefod','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Vis widgets på checkout-footeren. Vises kun, hvis man bruger plugin\'ets checkout-footer.','Classic' => 'Klassisk','Boxed' => 'I kasse','Split' => 'Split','Minimalist' => 'Minimalistisk','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Plugins til flydende checkout og leveringsdato fra CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Vi har opdaget, at du bruger plugins Delivery & Pickup Date Time for WooCommerce (gratis og PRO) af CodeRockz. Integrationen med disse plugins er blevet flyttet til Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Opgrader til PRO','Fluid Checkout database updated successfully' => 'Fluid Checkout-databasen er opdateret med succes','The database changes where applied successfully.' => 'Databaseændringerne blev anvendt med succes.','Dismiss' => 'Afslå','Fluid Checkout database update' => 'Opdatering af Fluid Checkout-databasen','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Der kræves nogle ændringer i databasen. Som med enhver opdatering anbefaler vi, at du <strong>tager en fuld sikkerhedskopi af din hjemmeside, før du fortsætter</strong>.','Update database' => 'Opdatering af database','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout er ikke kompatibel med Divi Builders kasselayout','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout har brug for den klassiske WooCommerce-kortkodebaserede checkout-formular for at fungere. Når du bruger Divi Builder til at tilpasse udseendet på betalingssiden, erstattes de klassiske kortkoder med brugerdefinerede widgets fra Divi Builder for hver del af betalingssiden. Disse brugerdefinerede widgets er ikke kompatible med Fluid Checkout.</p><p>Rediger venligst din checkout-side og erstat Divi Builder-widgets med en tekst-widget, der indeholder kortkoden <code>[woocommerce_checkout]</code>.</p>','Edit the checkout page' => 'Rediger checkout-siden','Read the documentation.' => 'Læs dokumentationen.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Germanized PRO multistep checkout-funktion skal deaktiveres, når du bruger Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Når du bruger Fluid Checkout, bliver flertrinsfunktionen fra Germanized PRO-plugin\'et unødvendig og kan forårsage <strong>kritiske fejl under behandlingen af nye ordrer</strong>. Deaktiver venligst Germanized PRO\'s multistep checkout-funktion i plugin-indstillingerne.','Go to Germanized settings' => 'Gå til tysksprogede indstillinger','Thanks for choosing Fluid Checkout!' => 'Tak, fordi du valgte Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Du har brugt pluginet i et stykke tid nu. Hvad synes du om det indtil videre? <Giv os en hurtig vurdering, vi sætter pris på enhver form for feedback, og det opmuntrer os til at blive ved med at forbedre pluginet :)','Rate the plugin' => 'Bedøm plugin\'et','I need help!' => 'Jeg har brug for hjælp!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Nogle funktioner i WooCommerce Checkout Manager by Quadlayers fungerer muligvis ikke som forventet, når du bruger den med Fluid Checkout. Læs <a href="%s">vores dokumentation</a> for at få flere oplysninger og alternative løsninger.','Read documentation' => 'Læs dokumentation','Don\'t show this again' => 'Vis ikke dette igen','Fluid Checkout PRO' => 'Væskekontrol PRO','More design templates' => 'Flere designskabeloner','Optimized cart page' => 'Optimeret side med indkøbskurv','Optimized order received / thank you page' => 'Optimeret ordre modtaget/takkeside','Edit cart contents at checkout page' => 'Rediger indholdet i indkøbskurven på betalingssiden','Account matching / user matching' => 'Kontomatchning / brugermatchning','Trust symbols on the cart and thank you pages' => 'Tillidssymboler på indkøbskurven og takkesiderne','More positions for the coupon code on the checkout page' => 'Flere positioner for kuponkoden på betalingssiden','International phone numbers' => 'Internationale telefonnumre','Gift messages and packing slips' => 'Gavebeskeder og pakkesedler','Local pickup and in-store collection' => 'Lokal afhentning og afhentning i butikken','EU-VAT Assistant' => 'EU-momsassistent','I already have it – Hide this offer' => 'Jeg har det allerede - Skjul dette tilbud','Activated' => 'Aktiveret','Address book' => 'Adressebog','Select an image' => 'Vælg et billede','Cart layout' => 'Layout af indkøbsvogn','Cart optimizations' => 'Optimering af indkøbskurve','Enable cart page optimizations' => 'Aktivér optimering af indkøbskurvens side','Header and footer template' => 'Skabelon til sidehoved og sidefod','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Styrer, om man vil bruge den distraktionsfrie sidehoved- og sidefod eller beholde det aktuelt aktive temas hoved- og sidefod.','Distraction free header and footer' => 'Distraktionsfri sidehoved og sidefod','Theme\'s header and footer' => 'Temaets sidehoved og sidefod','Cart elements' => 'Vognens elementer','Make the order summary stay visible on the cart page while scrolling' => 'Få ordreoversigten til at forblive synlig på siden med indkøbskurven, mens du scroller','Coupon codes' => 'Kuponkoder','Hidden' => 'Skjult','Before the cart items section' => 'Før sektionen med varer i indkøbskurven','Inside the cart items section' => 'Inde i sektionen for varer i indkøbskurven','After the cart items section' => 'Efter sektionen med varer i indkøbskurven','Before the shipping section' => 'Før forsendelsesafsnittet','After the shipping section' => 'Efter forsendelsesafsnittet','Before the order summary' => 'Før ordreoversigten','Inside the order summary' => 'Inde i ordreoversigten','Before the order totals' => 'Før ordretotalerne','After the order totals' => 'Når ordren er talt op','After the order summary' => 'Efter ordreoversigten','Shipping' => 'Forsendelse','Select position where to display the shipping costs and calculator on the cart page.' => 'Vælg den position, hvor forsendelsesomkostningerne og beregneren skal vises på siden med indkøbskurven.','Display as a cart section' => 'Vis som en sektion i indkøbskurven','Cross-sells' => 'Krydssalg','Select position where to display the cross-sells section on the cart page.' => 'Vælg den position, hvor krydssalgssektionen skal vises på siden med indkøbskurven.','Before the cart actions' => 'Før handlingerne i indkøbskurven','After the cart actions' => 'Efter indkøbskurvens handlinger','Layout of cross-sell items on the cart page.' => 'Layout af krydssalgsvarer på siden med indkøbskurven.','Optimized horizontal cross-sells layout' => 'Optimeret horisontalt krydssalgslayout','Theme\'s cross-sells layout' => 'Temas layout for krydssalg','Number of cross-sell items to display on the cart page' => 'Antal krydssalgsvarer, der skal vises på siden med indkøbskurven','Add widget areas to the cart page' => 'Tilføj widget-områder til siden med indkøbskurven','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Disse widgetområder bruges til at tilføje tillidssymboler og tillidsmærker på indkøbskurvsiden.','Checkout' => 'Kasse','Checkout layout' => 'Layout ved kassen','Design template' => 'Designskabelon','Dark mode' => 'Mørk tilstand','Enable dark mode' => 'Aktivér mørk tilstand','Logo image' => 'Logo-billede','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Vælg et billede, der skal vises i overskriften på betalingssiden. Gælder kun, når du bruger den distraktionsfri sidehoved og sidefod.','Header background color' => 'Overskriftens baggrundsfarve','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Vælg en baggrundsfarve til kassesidens header. Gælder kun, når du bruger den distraktionsfri sidehoved og sidefod.','HTML color value. ie: #f3f3f3' => 'HTML-farveværdi, f.eks: #f3f3f3','Page background color' => 'Sidens baggrundsfarve','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Vælg en baggrundsfarve til betalingssiden. Farven anvendes på <em>body</em>-elementet.','Footer background color' => 'Baggrundsfarve til sidefod','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Vælg en baggrundsfarve til kassesidens sidefod. Gælder kun, når du bruger den distraktionsfri header og footer.','Progress bar' => 'Fremdriftslinje','Display the checkout progress bar when using multi-step checkout layout' => 'Vis checkout-fremdriftslinjen, når du bruger multi-step checkout-layout','Make the checkout progress bar stay visible while scrolling' => 'Få checkout-fremdriftslinjen til at forblive synlig, mens du scroller','Express checkout' => 'Hurtig checkout','Enable the express checkout section' => 'Aktivér sektionen for ekspresbetaling','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Viser express checkout-sektionen ved checkout, når understøttede betalingsgateways har denne funktion aktiveret.','Display express checkout buttons in one line for larger screens' => 'Vis express checkout-knapper på én linje til større skærme','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Ignorer yderligere krævede checkout-felter, når du betaler med en kompatibel express checkout-betalingsgateway','Make the order summary stay visible while scrolling' => 'Få ordreoversigten til at forblive synlig, mens du scroller','Choose a background color for the order summary section.' => 'Vælg en baggrundsfarve til sektionen med ordreoversigt.','Highlight the order totals row in the order summary table' => 'Fremhæv rækken med ordretotaler i ordreoversigtstabellen','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Mest nyttigt, når afsnittet med ordreoversigten ikke har en fremhævet baggrundsfarve. Kan også anvendes på siderne Indkøbskurv, Modtaget ordre og Vis ordre, når du bruger Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Action-link på ordreoversigten ved kassen.','Edit cart link' => 'Rediger link til indkøbskurv','Cart items count' => 'Antal varer i indkøbskurven','Link to shop page' => 'Link til butiksside','Cart items' => 'Varer i indkøbskurven','Hide cart items errors at the checkout page' => 'Skjul fejl i indkøbskurven på betalingssiden','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Vis ikke fejlmeddelelsen for varer i indkøbskurven øverst på betalingssiden. Når du sender checkout-formularen for at gennemføre købet, vil disse fejlmeddelelser altid blive vist.','Place order' => 'Afgiv ordre','Define the position to display "Place order" and terms checkbox section.' => 'Bestem, hvor afkrydsningsfeltet "Afgiv ordre" og vilkår skal vises.','Some options might not be compatible with some plugins and themes.' => 'Nogle indstillinger er måske ikke kompatible med nogle plugins og temaer.','Below the payment section' => 'Under betalingssektionen','Below the order summary' => 'Under ordreoversigten','Both below the payment section and the order summary' => 'Både under betalingssektionen og ordreoversigten','Add widget areas to the checkout page' => 'Tilføj widget-områder til kassesiden','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Disse widgetområder bruges til at tilføje tillidssymboler og tillidsmærker på betalingssiden.','Display the coupon codes section title' => 'Vis titlen på sektionen med kuponkoder','Select position where to display the coupon codes section on the checkout page.' => 'Vælg den position, hvor afsnittet med kuponkoder skal vises på betalingssiden.','Before the checkout steps' => 'Før kassetrinene','As a substep before payment methods' => 'Som et mellemtrin før betalingsmetoder','As a substep after payment methods' => 'Som et undertrin efter betalingsmetoder','Default button style' => 'Standard knap-stil','"Add" link button' => '"Tilføj"-link-knap','Checkout fields' => 'Checkout-felter','Optional fields' => 'Valgfrie felter','Hide optional fields behind a link button' => 'Skjul valgfrie felter bag en link-knap','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Det anbefales at holde denne mulighed markeret for at reducere antallet af åbne inputfelter, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">læse forskningen</a>.','Do not hide "Address line 2" fields behind a link button' => 'Skjul ikke "Adresselinje 2"-felter bag en link-knap','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Anbefales kun, når de fleste kunder faktisk har brug for feltet "Adresselinje 2", eller når det er afgørende at få den rigtige leveringsadresse (f.eks. ved levering af fødevarer og andre letfordærvelige produkter).','Billing address' => 'Faktureringsadresse','Select position where to display the billing address section on the checkout page.' => 'Vælg den position, hvor faktureringsadresseafsnittet skal vises på betalingssiden.','As a step before shipping' => 'Som et skridt før forsendelse','As a sub-step before the shipping address section' => 'Som et undertrin før afsnittet om leveringsadresse','As a sub-step after the shipping address section' => 'Som et undertrin efter afsnittet om leveringsadresse','As a step after shipping' => 'Som et skridt efter forsendelse','As a sub-step before the payment section' => 'Som et undertrin før betalingsafsnittet','Force billing and shipping addresses to the same (single section)' => 'Tving fakturerings- og leveringsadresser til at være de samme (enkelt sektion)','Checkbox for "Same as shipping/billing address" checked by default' => 'Afkrydsningsfelt for "Samme som forsendelses-/faktureringsadresse" markeret som standard','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Afkrydsningsfeltet "Samme som forsendelsesadresse" starter som afkrydset som standard, når afsnittet om forsendelsesadresse vises først. <Afkrydsningsfeltet "Samme som faktureringsadresse" starter som standard med at være markeret, når faktureringsadressesektionen vises først. <br> Det anbefales at lade denne mulighed være markeret for at reducere antallet af åbne indtastningsfelter ved kassen betydeligt, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">læs forskningen</a>.','Highlight the billing address section in the checkout form' => 'Fremhæv sektionen for faktureringsadresse i checkout-formularen','Shipping address' => 'Leveringsadresse','Highlight the shipping address section in the checkout form' => 'Fremhæv sektionen for leveringsadresse i checkout-formularen','Shipping methods' => 'Forsendelsesmetoder','Choose in which position to display the shipping methods section.' => 'Vælg, hvor afsnittet om forsendelsesmetoder skal vises.','Before shipping address' => 'Før leveringsadresse','After shipping address' => 'Efter leveringsadresse','Local pickup' => 'Lokal afhentning','Removes shipping address section when a local pickup shipping method is selected.' => 'Fjerner sektionen med leveringsadresse, når der er valgt en leveringsmetode med lokal afhentning.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Erstatter leveringsadressen med afhentningsstedets placering, når der er valgt en lokal afhentningsforsendelsesmetode.','Choose which address to save as the shipping address for local pickup orders.' => 'Vælg, hvilken adresse der skal gemmes som leveringsadresse for lokale afhentningsordrer.','Save the selected pickup location' => 'Gem det valgte afhentningssted','Save same as the billing address' => 'Gem det samme som faktureringsadressen','Do not save any shipping address' => 'Gem ikke nogen leveringsadresse','Company name field for shipping address' => 'Felt med firmanavn til leveringsadresse','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Ændre synligheden for firmanavnsfeltet i sektionen for leveringsadresse på checkout-formularen.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Hvis feltet er indstillet som "valgfrit", hvilket er standardtilstanden for synlighed, vil der ikke blive foretaget nogen ændringer, så andre plugins kan foretage de ændringer, de har brug for.','Hidden (remove field)' => 'Skjult (fjern felt)','Optional' => 'Valgfrit','Required' => 'Påkrævet','Add shipping phone field to the checkout form.' => 'Tilføj et felt til forsendelsestelefon til checkout-formularen.','Choose in which step to display the shipping phone field.' => 'Vælg, i hvilket trin du vil vise feltet for forsendelsestelefon.','Contact step' => 'Kontakt trin','Billing phone' => 'Faktureringstelefon','Add billing phone field to the checkout form.' => 'Tilføj et felt til faktureringstelefon til checkout-formularen.','Choose in which step to display the billing phone field.' => 'Vælg, i hvilket trin du vil vise feltet for faktureringstelefon.','Show country code beside the flag' => 'Vis landekode ved siden af flaget','Show an example of a valid phone number inside phone fields' => 'Vis et eksempel på et gyldigt telefonnummer i telefonfelter','Do not change placeholders' => 'Ændr ikke pladsholdere','Show if not defined' => 'Vis, hvis ikke defineret','Always show' => 'Vis altid','Order notes' => 'Bestil noter','Define the visibility of the additional order notes field.' => 'Definer synligheden af feltet for ekstra ordrenoter.','Gift options' => 'Muligheder for gaver','Allow customers to add a gift message and other gift related options to the order.' => 'Giv kunderne mulighed for at tilføje en gavebesked og andre gaverelaterede muligheder til ordren.','Display the gift message as part of the order details table instead of a separate section' => 'Vis gavebeskeden som en del af tabellen med ordreoplysninger i stedet for en separat sektion','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Denne indstilling påvirker ordrebekræftelsessiden (takkesiden) og ordreoplysninger på kontosider, e-mails og pakkesedler.','Account matching' => 'Matchning af konto','Enable the account matching feature' => 'Aktivér funktionen til kontomatchning','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Tilknyt gæstekundens ordrer til deres eksisterende konto, hvis der allerede findes en konto med kundens kontaktoplysninger.','Display message when an account exists with the email address provided' => 'Vis besked, når der findes en konto med den angivne e-mailadresse','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Erstatter felterne til kontooprettelse med en meddelelse og mulighed for at logge ind. I nogle sammenhænge kan det anbefales at lade denne mulighed være deaktiveret for at beskytte kundernes privatliv.','Dashboard' => 'Dashboard','Integrations' => 'Integrationer','License keys' => 'Licensnøgler','Visit our website for more information about our plugins and add-ons.' => 'Besøg vores hjemmeside for at få flere oplysninger om vores plugins og add-ons.','Order pay page' => 'Bestil betalingsside','Order pay' => 'Bestil løn','Enable order pay page optimizations' => 'Aktiver optimering af ordrebetalingsside','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Ændrer layoutet på betalingssiden for eksisterende ordrer, der afventer betaling fra kunden.','Add widget areas to the order pay page' => 'Tilføj widget-områder til betalingssiden for ordrer','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Disse widgetområder bruges til at tilføje tillidssymboler og tillidsmærker på betalingssiden for ordren.','Thank you page & order details layout' => 'Layout for takkeside og ordreoplysninger','Order details optimizations' => 'Optimering af bestillingsdetaljer','Enable thank you page and order details optimizations' => 'Aktiver optimering af takkeside og ordreoplysninger','Changes the layout of order details on the thank you page and account pages.' => 'Ændrer layoutet af ordreoplysninger på takkesiden og kontosiderne.','Enable order details customizations on email notifications' => 'Aktiver tilpasninger af ordreoplysninger på e-mailnotifikationer','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Vis nye sektioner og ændr rækkefølgen af sektioner i e-mailnotifikationer. Stilarter for ordreoplysninger på e-mailnotifikationer forbliver uændrede.','Thank you page' => 'Tak side','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Disse indstillinger påvirker takkesiden, også kendt som siderne for modtaget ordre eller ordrebekræftelse.','Order details layout' => 'Layout for ordreoplysninger','Display the order details with wide layout on the thank you page' => 'Vis ordreoplysningerne med bredt layout på takkesiden','Add widget areas to the thank you page' => 'Tilføj widget-områder til takkesiden','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Disse widgetområder bruges til at tilføje tillidssymboler og tillidsbadges på takkesiden.','Order actions' => 'Bestil handlinger','Choose in which position to display the order actions.' => 'Vælg, i hvilken position ordrehandlingerne skal vises.','Inside the order overview' => 'Inde i ordreoversigten','After the order overview' => 'Efter ordreoversigten','After order sections' => 'Efter ordreafsnit','Order status' => 'Bestillingsstatus','Display the order status progress bar' => 'Vis statuslinjen for ordrestatus','Choose in which position to display the section.' => 'Vælg, hvilken position sektionen skal vises i.','After the order overview and payment instructions' => 'Efter ordreoversigten og betalingsinstruktioner','Before the order items section' => 'Før sektionen med bestillingsvarer','Inside the order items section' => 'Inde i sektionen for bestillingsvarer','After the order items section' => 'Efter sektionen med bestillingsvarer','On the sidebar' => 'På sidepanelet','Order downloads' => 'Bestil downloads','Gift message' => 'Gavebesked','Tools' => 'Værktøjer','Troubleshooting' => 'Fejlfinding','Debug options' => 'Fejlfindingsindstillinger','Debug mode' => 'Fejlfindingstilstand','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Brug af debug-tilstand påvirker hjemmesidens ydeevne. Brug kun denne mulighed under fejlfinding.','Load unminified assets' => 'Indlæs uminificerede aktiver','Enhanced select fields' => 'Forbedrede markeringsfelter','Fix automatic zoom-in on form fields' => 'Fix automatisk zoom-in på formularfelter','Set <code>font-size</code> inside form fields to 16px' => 'Sæt <code>font-size</code> i formularfelter til 16px','Fluid Checkout' => 'Væskekontrol','Settings' => 'Indstillinger','Support' => 'Støtte','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Opgrader til PRO</a> for at låse op for flere muligheder.','(PRO)' => '(PRO)','(experimental)' => '(eksperimentel)','Please verify your phone number.' => 'Bekræft venligst dit telefonnummer.','The Bluehost Plugin' => 'Bluehost-plugin\'et','Custom fields' => 'Brugerdefinerede felter','Enable custom shipping email field' => 'Aktivér brugerdefineret e-mail-felt til forsendelse','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Når det er aktiveret, tilføjes feltet for forsendelses-e-mail fra Bluehost-plugin\'et til checkout-formularen.','Captcha Pro by BestWebSoft' => 'Captcha Pro af BestWebSoft','Captcha position' => 'Captcha-position','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Definer den position, hvor captcha-afsnittet skal vises. Nogle positioner fungerer muligvis ikke, afhængigt af den valgte captcha-type.','Selecting a pickup point is required before proceeding.' => 'Det er nødvendigt at vælge et opsamlingssted, før man kan fortsætte.','Pickup point' => 'Afhentningssted','Pickup point not selected yet.' => 'Opsamlingssted ikke valgt endnu.','Pickup point:' => 'Opsamlingssted:','Mailchimp for WooCommerce' => 'Mailchimp til WooCommerce','Subscribe checkbox' => 'Afkrydsningsfelt for abonnement','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Overstyr placeringen af afkrydsningsfeltet for abonnement på betalingssiden, og vis det altid på kontakttrinnet','Before Shipping Address' => 'Før leveringsadresse','(originally "%s")' => '(oprindeligt "%s")','After Shipping Address' => 'Efter leveringsadresse','Selecting a collection point is required when shipping with FermoPoint.' => 'Det er nødvendigt at vælge et opsamlingssted, når man sender med FermoPoint.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Hvis afkrydset, informeres brugerne om skrivefejl i en e-mail. (Denne funktion er deaktiveret, fordi Fluid Checkout tilbyder funktionen. Ændringer af denne indstilling vil ikke træde i kraft)','Enable Mail Check: (disabled feature)' => 'Aktivér postkontrol: (deaktiveret funktion)','Carrier:' => 'Transportør:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce e-mail-marketing','Sign up checkbox position' => 'Placering af tilmeldingsboks','Move the sign up checkbox to the contact step' => 'Flyt afkrydsningsfeltet for tilmelding til kontakttrinnet','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Når den er aktiveret, flyttes afkrydsningsfeltet til kontakttrinnet uafhængigt af den visningsplacering, der er defineret i Sendinblue-pluginindstillingerne.','Theme Betheme' => 'Tema Betheme','Checkout progress' => 'Fremskridt i checkout','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Udfør sektionen med kassetrin fra Betheme på siderne med kassen, indkøbskurven og den modtagne ordre.','Theme Fennik' => 'Tema Fennik','Breadcrumbs' => 'Brødkrummer','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Send brødkrummesektionen fra Fennik-temaet, når du bruger Fluid Checkout-header og -footer.','Theme Go' => 'Tema Gå','My account layout' => 'Min kontos layout','Enable wide layout on "My account" page.' => 'Aktivér bredt layout på siden "Min konto".','Theme Impreza' => 'Tema Impreza','Header' => 'Overskrift','Spacing for site header at the checkout page (in pixels)' => 'Afstand til sidehoved på kassesiden (i pixels)','Only applicable when using the Impreza theme header at the checkout page.' => 'Gælder kun, når du bruger Impreza-temaoverskriften på betalingssiden.','Theme Kapee' => 'Tema Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Udfør afsnittet med kassetrin fra Kapee-temaet på siderne med kassen, indkøbskurven og den modtagne ordre.','Theme Porto' => 'Tema Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Udfør afsnittet om kassetrin fra Porto-temaet på siderne med kassen, indkøbskurven og den modtagne ordre.','Theme Pressmart' => 'Tema Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Udfør afsnittet om kassetrin fra Pressmart-temaet på siderne med kassen, indkøbskurven og den modtagne ordre.','Theme The Gem' => 'Tema for ædelstenen','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Udfør afsnittet om kassetrin fra Gem-temaet, når du bruger Fluid Checkout-header og -footer.','Theme Woodmart' => 'Tema Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Udfør afsnittet om kassetrin fra Woodmart-temaet, når du bruger Fluid Checkout header og footer.','Checkout options' => 'Muligheder for checkout','Disable the theme checkout options' => 'Deaktiver temaets checkout-muligheder','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Indstillingerne vis produktbillede, mængdefelt, fjern-knap og link til produktside, som er tilføjet af temaet, er som standard deaktiveret.','Theme Atomion' => 'Tema Atomion','Order progress' => 'Fremskridt i bestillingen','Display order progress from the theme' => 'Vis ordreforløbet fra temaet','Display the form field labels visible on the page' => 'Vis formularfeltets etiketter synligt på siden','It is recommended to keep this option enabled for a better user experience.' => 'Det anbefales at lade denne indstilling være aktiveret for at få en bedre brugeroplevelse.','Theme ZK Nito' => 'Tema ZK Nito','Add extra fields to the checkout form' => 'Tilføj ekstra felter til checkout-formularen','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Tilføjer et ekstra felt til forsendelsesmail og -telefon til sektionen for forsendelsesadresse.','Go to the home page' => 'Gå til startsiden','Skip to content' => 'Spring til indhold','Create an account' => 'Opret en konto','Log in to your account' => 'Log ind på din konto','Already have an account?' => 'Har du allerede en konto?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Logget ind som %1$s. <a href="%2$s">Log ud</a>.','Your order has a total amount due of %s. No further payment is needed.' => 'Din ordre har et samlet skyldigt beløb på %s. Der er ikke behov for yderligere betaling.','Close and continue with checkout' => 'Luk og fortsæt med checkout','Continue' => 'Fortsæt','Parcel terminal' => 'Pakketerminal','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Denne widget er blevet erstattet af Fluid Checkout. </p><p>Når du bruger Fluid Checkout, skal betalingssiden bruge den originale WooCommerce-kortkode <code>[woocommerce_checkout]</code> for at fungere korrekt.</p><p>For mere information, besøg Fluid Checkout-dokumentationen.</p>','Theme The7' => 'Temaet The7','Additional header sections' => 'Yderligere overskriftssektioner','Output additional header sections if enabled in the theme settings.' => 'Udlæs ekstra overskriftssektioner, hvis de er aktiveret i temaindstillingerne.','More information' => 'Mere information','Pick a Locker' => 'Vælg et skab','Page template' => 'Skabelon til side','Use `Order confirmation` page template for block-based themes' => 'Brug sideskabelonen `Bestillingsbekræftelse` til blokbaserede temaer','Only applies when using a block-based theme.' => 'Gælder kun, når man bruger et blokbaseret tema.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Betalingsformular','Apply styles to the Stripe payment form fields' => 'Anvend stilarter på Stripe-betalingsformularens felter','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Når det er aktiveret, vil Fluid Checkout anvende stilarter, der er optimeret til kompatibilitet med plugin\'et. Det kan være en god idé at deaktivere dette, hvis du bruger brugerdefinerede stilarter til felterne i Stripe-betalingsformularen.','Theme Nyture' => 'Tema Nyktur','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Udfør afsnittet om kassetrin fra Nyture-temaet, når du bruger Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Giver kunderne mulighed for at betale for ordrer, der enten er oprettet manuelt af butiksadministratoren eller ikke er gennemført ved kassen.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Plugin\'et WooCommerce Checkout Manager fra Quadlayers er ikke kompatibelt med Fluid Checkout','Company name field for billing address' => 'Firmanavnsfelt til faktureringsadresse','Change visibility for the company name field for the billing address section on the checkout form.' => 'Ændre synligheden for firmanavnsfeltet i sektionen for faktureringsadresse på checkout-formularen.','Theme Bookshelf' => 'Tema-boghylde','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Udfør afsnittet om betalingstrin fra Bookshelf-temaet, når du bruger Fluid Checkout.','Account password' => 'Adgangskode til konto','An account will be created with the information provided at checkout when completing the order.' => 'Der oprettes en konto med de oplysninger, der angives ved kassen, når du gennemfører bestillingen.','Choose the style of the progress bar.' => 'Vælg stilen på statuslinjen.','Bars' => 'Stænger','Theme Ireca' => 'Tema Ireca','WooCommerce page layout' => 'Layout af WooCommerce-side','Force wide layout on WooCommerce pages' => 'Tving bredt layout på WooCommerce-sider','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Dette sikrer, at indholdssektionen ikke er for smal på WooCommerce-sider, herunder checkout-, kurv-, ordre modtaget-, ordrebetalt- og kontosider.','WooCommerce Smart Coupons' => 'WooCommerce smarte kuponer','Position on checkout page' => 'Placering på kassesiden','Choose where to display the available coupons section on the checkout page.' => 'Vælg, hvor afsnittet om tilgængelige kuponer skal vises på betalingssiden.','Before the progress bar' => 'Før statuslinjen','After the progress bar' => 'Efter statuslinjen','Before coupon codes section' => 'Før sektionen med kuponkoder','Format phone numbers according to the rules for each country.' => 'Formater telefonnumre i henhold til reglerne for hvert land.','Use precise phone number validation' => 'Brug præcis validering af telefonnumre','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Dette er en eksperimentel funktion og fungerer muligvis ikke som forventet i alle opsætninger. Brug den med forsigtighed.','Phone number validation types used when precise validation is enabled.' => 'Valideringstyper for telefonnumre, der bruges, når præcis validering er aktiveret.','Mobile' => 'Mobil','Fixed line' => 'Fastnet','Toll free' => 'Gratis opkald','Or' => 'Eller','Contact' => 'Kontakt','Multi step' => 'Flere trin','2 columns' => '2 søjler','1 column' => '1 søjle','Before checkout steps' => 'Før checkout-trin','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Når du bruger kasselayoutet <em>"1 kolonne"</em>, er denne mulighed altid indstillet til <em>"Før kassetrin"</em> og gælder også for desktopvisning.','Position for the extra order summary section on mobile.' => 'Position for den ekstra sektion med ordreoversigt på mobilen.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Indstillingen <em>"På sidens overskrift"</em> gælder kun, når du bruger den distraktionsfri overskrift.','On the site header (requires distraction-free header)' => 'På sidens header (kræver distraktionsfri header)','Initial state for the expansible order summary section on mobile.' => 'Indledende tilstand for den udvidelige sektion med ordreoversigt på mobilen.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Vi anbefaler at indstille den som <em>udvidet</em> for følgende lande på grund af lovkrav: <strong>Tyskland</strong>, <strong>Østrig</strong>, <strong>Schweiz</strong>, <strong>Nederland</strong>, <strong>Polen</strong>, <strong>Belgien</strong> og <strong>Frankrig</strong>.','Collapsed' => 'Kollapset','Expanded' => 'Udvidet','Do not show' => 'Må ikke vises','yes' => 'ja','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Feltet til leveringstelefonnummer kan blive markeret som "obligatorisk", hvis afsnittet med faktureringsadressen vises efter afsnittet med leveringsadressen, og feltet til faktureringsnummer er angivet som "obligatorisk". Dette er nødvendigt for at sikre, at leveringsadressen kan kopieres til faktureringsadressen, når denne indstilling er markeret; ellers kan kunden muligvis ikke gennemføre betalingsprocessen.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Feltet til faktureringsnummer kan angives som »obligatorisk«, hvis afsnittet med faktureringsadresse vises før afsnittet med leveringsadresse, og feltet til leveringsnummer er angivet som »obligatorisk«. Dette er nødvendigt for at sikre, at leveringsadressen kan kopieres til faktureringsadressen, når denne mulighed er markeret; ellers kan kunden muligvis ikke gennemføre betalingsprocessen.','Settings profiles' => 'Indstillingsprofiler','Settings profile' => 'Indstillingsprofil','You do not have permission to perform this action.' => 'Du har ikke tilladelse til at udføre denne handling.','You do not have permission to activate plugins.' => 'Du har ikke tilladelse til at aktivere plugins.','Missing plugin.' => 'Manglende plugin.','Plugin activated.' => 'Plugin er aktiveret.','The following changes will be applied:' => 'Følgende ændringer vil blive gennemført:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Siden Fluid Checkout 5.0 gemmes indstillingerne på en anden måde. De gamle indstillinger gemmes stadig i databasen, så det er muligt at nedgradere til tidligere versioner, hvis det bliver nødvendigt.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Din butik har kørt i cirka 2 uger med de nye indstillinger, så du har haft mulighed for at rydde op i de gamle indstillinger, der var gemt i databasen. Vær opmærksom på, at hvis du efter oprydningen har brug for at nedgradere til tidligere versioner af pluginet, vil det anvende standardværdier for alle indstillinger.','Fluid Checkout settings cleanup' => 'Oprydning af indstillingerne for »Fluid Checkout«','Delete leftover options' => 'Slet overskydende valgmuligheder','Help us improve Fluid Checkout' => 'Hjælp os med at forbedre Fluid Checkout','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Del anonyme rapporter om dit webmiljø med Fluid Checkout for at få hurtigere support og hjælpe os med at forbedre kompatibiliteten og måle effekten. Der indgår ingen kunde-, bruger- eller følsomme data. Du kan til enhver tid vælge, hvad der deles, under indstillingerne under »Værktøjer«.','Enable site environment reports' => 'Aktivér rapporter om webstedsmiljøet','Review settings' => 'Gennemse indstillinger','This preview has expired. Reload the admin page to start a new preview.' => 'Denne forhåndsvisning er udløbet. Genindlæs administrationssiden for at starte en ny forhåndsvisning.','Preview expired' => 'Forhåndsvisningen er udløbet','Orders cannot be placed in the preview.' => 'Der kan ikke afgives ordrer i forhåndsvisningen.','Logging in is not available in the preview.' => 'Det er ikke muligt at logge ind i forhåndsvisningen.','Accounts cannot be created in the preview.' => 'Der kan ikke oprettes konti i forhåndsvisningen.','Requests to other sites are blocked in the preview.' => 'Forespørgsler til andre websteder blokeres i forhåndsvisningen.','Processing…' => 'Behandler…','Something went wrong. Please try again.' => 'Der opstod en fejl. Prøv venligst igen.','Activate plugin' => 'Aktivér plugin','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO – Den komplette kassepakke','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Alle PRO-funktioner + alle tillægsmoduler – alt til én pris. Designskabeloner, optimerede sider til indkøbskurv og ordrebekræftelse, konto-sammenkobling og meget mere.','Optimized order pay page' => 'Optimeret betalingsside for ordrer','Express checkout buttons from supported payment methods' => 'Knapper til hurtig betaling fra understøttede betalingsmetoder','Delayed account creation' => 'Forsinket oprettelse af konto','Address autocomplete with Google Maps APIs' => 'Automatisk udfyldning af adresser med Google Maps-API’er','Multiple saved addresses with the address book' => 'Flere gemte adresser i adressebogen','EU-VAT assistant' => 'EU-moms-assistent','Hide this section' => 'Skjul dette afsnit','Learn more' => 'Læs mere','Get early access' => 'Få tidlig adgang','Activate add-on' => 'Aktivér tilføjelsesprogram','Get more out of your checkout journey' => 'Få mere ud af din betalingsproces','Test API key' => 'Test API-nøgle','Guided setup' => 'Vejledning til opsætning','Options' => 'Valgmuligheder','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Konfigurer layout og design under <a href="%s">betalingsmuligheder</a>.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Aktivér gæstekøb og/eller gennemgå <a href="%s">indstillingerne for kundekonti</a>.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Aktivér de optimerede sider <a href="%1$s">indkøbskurv</a>, <a href="%2$s">tak</a> og <a href="%3$s">betaling af ordre</a>.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Aktivér <a href="%s">automatisk udfyldning af adresser</a> fra Google Maps.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Aktivér flere gemte adresser med <a href="%s">adressebogen</a>.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Tjek, om der findes <a href="%s">integrationsmuligheder</a> til det tema eller de andre plugins, du har installeret.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Få hurtigere support, og hjælp os med at forbedre kompatibiliteten og måle effekten. <a href="%s">Aktivér brugssporing</a> i værktøjets indstillinger.','Missing settings tab.' => 'Fanen »Indstillinger« mangler.','Getting started' => 'Kom godt i gang','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Fantastisk! Din betalingsside kører nu på Fluid Checkout.</strong> Her er et par trin til at komme i gang:','Completed' => 'Afsluttet','Preview report data' => 'Vis en forhåndsvisning af rapportdataene','Send now' => 'Send nu','Auto-detect' => 'Automatisk genkendelse','Afrikaans' => 'afrikaans','Albanian' => 'Albansk','Amharic' => 'Amharisk','Arabic' => 'Arabisk','Armenian' => 'armensk','Azerbaijani' => 'aserbajdsjansk','Basque' => 'baskisk','Belarusian' => 'hviderussisk','Bengali' => 'bengalsk','Bosnian' => 'bosnisk','Bulgarian' => 'bulgarsk','Burmese' => 'burmesisk','Catalan' => 'katalansk','Chinese' => 'Kinesisk','Chinese (Simplified)' => 'Kinesisk (forenklet)','Chinese (Hong Kong)' => 'Kinesisk (Hongkong)','Chinese (Traditional)' => 'Kinesisk (traditionel)','Croatian' => 'Kroatisk','Czech' => 'Tjekkisk','Danish' => 'Dansk','Dutch' => 'hollandsk','English' => 'Engelsk','English (Australian)' => 'Engelsk (australsk)','English (Great Britain)' => 'Engelsk (Storbritannien)','Estonian' => 'Estisk','Farsi' => 'Farsi','Finnish' => 'Finsk','Filipino' => 'Filippinsk','French' => 'Fransk','French (Canadian)' => 'Fransk (canadisk)','Galician' => 'galicisk','Georgian' => 'georgisk','German' => 'Tysk','Greek' => 'Græsk','Gujarati' => 'gujarati','Hebrew' => 'Hebraisk','Hindi' => 'Hindi','Hungarian' => 'Ungarsk','Icelandic' => 'Islandsk','Indonesian' => 'Indonesisk','Italian' => 'Italiensk','Japanese' => 'Japansk','Kannada' => 'Kannada','Kazakh' => 'kasakhisk','Khmer' => 'Khmer','Korean' => 'Koreansk','Kyrgyz' => 'Kirgisisk','Lao' => 'Laos','Latvian' => 'lettisk','Lithuanian' => 'Litauisk','Macedonian' => 'makedonsk','Malay' => 'Malaysisk','Malayalam' => 'malayalam','Marathi' => 'Marathi','Mongolian' => 'mongolsk','Nepali' => 'Nepalesisk','Norwegian' => 'Norsk','Polish' => 'Polsk','Portuguese' => 'Portugisisk','Portuguese (Brazil)' => 'Portugisisk (Brasilien)','Portuguese (Portugal)' => 'Portugisisk (Portugal)','Punjabi' => 'punjabi','Romanian' => 'Rumænsk','Russian' => 'Russisk','Serbian' => 'Serbisk','Sinhalese' => 'singalesisk','Slovak' => 'Slovakisk','Slovenian' => 'slovensk','Spanish' => 'Spansk','Spanish (Latin America)' => 'Spansk (Latinamerika)','Swahili' => 'swahili','Swedish' => 'Svensk','Tamil' => 'Tamil','Telugu' => 'Telugu','Thai' => 'Thai','Turkish' => 'Tyrkisk','Ukrainian' => 'ukrainsk','Urdu' => 'Urdu','Vietnamese' => 'Vietnamesisk','Zulu' => 'Zulu','Google address autocomplete' => 'Googles adresseautofyldning','Google Places API version' => 'Google Places API-version','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Vælg, hvilken version af Google Places API du vil bruge. Vi anbefaler, at du skifter til det nye Places API så hurtigt som muligt.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Vi anbefaler, at du bruger »Places API (New)«, da Google fra den 1. marts 2025 vil overføre versionen »Places API (Legacy)« til »Legacy«-status. Det betyder, at du ikke længere vil kunne aktivere denne tjeneste for nye API-nøgler, og at denne version af API’et på sigt ikke længere vil være tilgængelig. Eksisterende konti, der allerede bruger Legacy API\'en, kan fortsætte med at fungere uden afbrydelser.','(Recommended)' => '(Anbefalet)','Google API key' => 'Google API-nøgle','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Indsæt din Google API-nøgle, og brug testknappen til at kontrollere, at den fungerer på denne hjemmeside. Sørg for, at nøglen er gyldig og godkendt til dit domæne, ellers kan adressefeltet blive blokeret, hvilket forhindrer kunderne i at gennemføre deres bestillinger.','Enable Google address autocomplete' => 'Aktivér automatisk udfyldning af adresser fra Google','Enable address autocompletion using the Google Maps APIs.' => 'Aktivér automatisk adressefyldning ved hjælp af Google Maps-API’erne.','Google API language' => 'Google API-sprog','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Dette sprog vil blive brugt til at vise adresseforslag fra Google Places API, og adresserne vil også blive autoudfyldt på dette sprog.','Result types' => 'Resultattyper','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Lad feltet være tomt for at acceptere alle typer resultater, hvilket normalt giver bedre match. <a href="%s" target="_blank">Se dokumentationen for flere detaljer</a>. <br>Vælg op til 5 typer adressesøgeresultater, der skal vises i felterne til automatisk adressefyldning. <br>Besøg dokumentationen til Google Maps for at få mere at vide om de <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">understøttede typer</a>.','Result types (Legacy API)' => 'Resultattyper (ældre API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Hvilken type adressesøgeresultater der skal returneres, når man bruger Places API (Legacy). <br>Besøg dokumentationen til den ældre version af Google Places API for at få mere at vide om de <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">understøttede typer</a>.','Company fields' => 'Virksomhedsfelter','Enable autocomplete for the company name if available' => 'Aktivér autofuldførelse for firmanavnet, hvis denne funktion er tilgængelig','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Aktivér autofuldførelse af feltet »Virksomhed« med oplysninger om virksomhedsnavnet, når disse returneres fra Google Maps-API’erne.','Business search' => 'Virksomhedssøgning','Enable search for businesses in the company field' => 'Aktivér søgning efter virksomheder i feltet »Virksomhed«','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Aktivér forslag til adresser, der er knyttet til en virksomhed, når der indtastes i feltet »Virksomhed«, og udfyld derefter automatisk alle adressefelter, når en virksomhed vælges blandt forslagene.','Company result types' => 'Typer af virksomhedsresultater','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Vælg op til 5 typer af adressesøgeresultater, der skal vises ved autofuldførelse af virksomhedsfelter. <br>Den anbefalede værdi er <code>virksomhed</code>, som omfatter de fleste typer virksomheder. <br>Lad feltet være tomt for at acceptere alle typer resultater, herunder resultater, der ikke er relateret til virksomheder. <br>Besøg dokumentationen til Google Maps for at få mere at vide om de <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">understøttede typer</a>.','Google logo' => 'Google-logoet','Show text and logo "Powered by Google"' => 'Vis teksten og logoet »Powered by Google«','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Når denne indstilling er markeret, vises teksten og logoet »Powered by Google« nederst i feltet med forslag til automatisk udfyldning af adresser.','Brasil API address autocomplete' => 'Automatisk udfyldning af adresser via Brasil API','Brasil API' => 'Brasil API','Enable Brasil API address autocomplete for CEP fields' => 'Aktivér automatisk udfyldning af adresser via Brasil API for CEP-felter','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Brug Brasil API til at hente og udfylde adresser automatisk ved hjælp af feltet CEP/postnummer. Gælder kun for brasilianske adresser.','API version' => 'API-version','Choose which version of the Brasil API CEP method to use.' => 'Vælg, hvilken version af Brasil API CEP-metoden der skal bruges.','Address book migration' => 'Overførsel af adressebog','WooCommerce addresses' => 'WooCommerce-adresser','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Kopier eksisterende leverings- og faktureringsadresser fra WooCommerce til kundernes adressebog.','Enable the address book feature' => 'Aktivér adressebogsfunktionen','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Giv kunderne mulighed for at gemme flere adresser og angive en standardadresse, der skal bruges til forsendelse og fakturering.','Address labels' => 'Adressemærkater','Allow customers to add a custom label for each address' => 'Giv kunderne mulighed for at tilføje en brugerdefineret etiket til hver adresse','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Adressemærker gør det nemmere for kunderne at skelne mellem deres gemte adresser (f.eks.: »Mors hus«). Adressemærkerne er fortrolige for kunderne og vises eller udskrives ikke på siden med ordreoplysninger eller på fakturaer.','Display layout' => 'Skærmlayout','Choose how saved addresses are displayed at checkout and on the cart.' => 'Vælg, hvordan gemte adresser skal vises ved kassen og i indkøbskurven.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Gælder ved kassen og i indkøbskurven. Gemte adresser på kontosiden vises altid i kortformat.','Address cards' => 'Adressekort','Address list' => 'Adresseliste','Dropdown field' => 'Rullemenufelt','Address search' => 'Adressesøgning','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Vis filteret til adressesøgning på brugergrænsefladen, når kunden har mindst dette antal gemte adresser til rådighed.','Not used when display layout is set to dropdown field.' => 'Anvendes ikke, når skærmlayoutet er indstillet til et rullemenufelt.','Addresses' => 'Adresser','Enable cart page optimizations to see more options' => 'Aktivér optimeringer af indkøbskurvsiden for at se flere muligheder','Sticky order summary' => 'Oversigt over faste ordrer','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Vælg, hvor afsnittet med rabatkoder skal vises på indkøbskurvsiden. Gælder kun, hvis AJAX-indkøbskurv er aktiveret, og hvis brugen af rabatkoder er aktiveret i WooCommerce-indstillingerne.','Layout of cross-sell' => 'Oversigt over krydssalg','Cross-sells displayed' => 'Visning af krydssalg','Items' => 'Varer','Cart page optimization' => 'Optimering af indkøbskurvsiden','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Giv din indkøbskurv det samme overskuelige og konverteringsorienterede layout som din kasse.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Sørg for, at indkøbskurvens layout stemmer overens med betalingssiden, så købsforløbet fremstår ensartet.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Sørg for, at indkøbskurven altid opdateres i baggrunden, så der ikke skal genindlæses hele siden, når mængderne ændres.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Placer rabatkoder, forsendelsesoplysninger og krydssalg præcis der, hvor de giver de bedste resultater.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Sørg for, at ordresammendraget forbliver synligt, når man ruller ned, og tilføj tillidssymboler de steder, hvor kunderne har brug for tryghed.','Columns' => 'Kolonner','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Generelle designskabeloner til betalingstrinene, ordresammendraget og andre afsnit. Gælder for siderne til betaling, indkøbskurv, tak (ordre modtaget) og visning af ordre.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Når man bruger layoutet <em>"1 kolonne"</em> sammen med designskabelonen <em>"Split"</em>, vises en højre kolonne kun, hvis widgetområdet i sidens sidebjælke er aktivt (sidebjælke ved kassen, sidebjælke ved indkøbskurven eller sidebjælke ved modtaget ordre). I alle andre tilfælde forbliver siden som en enkelt kolonne med »Split«-formatering.','Split column background' => 'Delt kolonnebaggrund','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Vælg en baggrundsfarve til den sekundære kolonne i »Split«-designet. Lad feltet være tomt for at bruge baggrundsfarven fra ordresammendraget.','Page templates' => 'Sideskabeloner','Checkout template' => 'Kasseside-skabelon','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Anbefales for at mindske distraktioner ved kassen. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Læs undersøgelsen om forladte indkøbskurve</a>.','Sticky progress bar' => 'Fast fremskridtsbjælke','Progress bar style' => 'Stil på statusbjælken','Order totals' => 'Ordretotaler','Background color' => 'Baggrundsfarve','Action link' => 'Handlingslink','Mobile order summary' => 'Oversigt over mobilbestillinger','Mobile initial state' => 'Mobilens starttilstand','Enable editing cart items at checkout' => 'Aktivér redigering af varer i indkøbskurven ved kassen','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Giv kunderne mulighed for at ændre produktmængder eller fjerne varer direkte på betalingssiden.','Cart item errors' => 'Fejl i indkøbskurven','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Dette gælder kun, hvis kuponkoden vises som et separat afsnit på betalings- eller indkøbskurvsiderne, og hvis brugen af kuponkoder er aktiveret i WooCommerce-indstillingerne.','Coupon codes position' => 'Placering af kuponkoder','Apply coupon button' => 'Knappen »Anvend kupon«','Select style of the "apply coupon" button.' => 'Vælg stil for knappen »Anvend kupon«.','Address line 2' => 'Adresse, linje 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Denne indstilling gælder både for afsnittene »Kasse« og »Lokal afhentning«. I afsnittet »Lokal afhentning« bestemmer den desuden, om valgmuligheden »Forsendelse/Afhentning« vises inden for afsnittet om forsendelsesmetoder (før adressen) eller som et separat afsnit (efter).','Customer accounts' => 'Kundekonti','Guest checkout' => 'Gæstekasse','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Indstillinger for gæstekøb, login og oprettelse af konto findes på indstillingssiden »WooCommerce-konti«. De administreres her for at gøre det nemmere for dig, og så du kan bruge forskellige værdier for hver indstillingsprofil.','Allow customers to checkout without an account' => 'Giv kunderne mulighed for at gennemføre købet uden en konto','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Anbefales</strong>, så kunderne ikke bliver bedt om at oprette en konto eller logge ind under betalingsprocessen, hvilket kan medføre lavere konverteringsrater.','When disabled, customers must log in or create an account to complete the purchase.' => 'Når denne funktion er deaktiveret, skal kunderne logge ind eller oprette en konto for at gennemføre købet.','Login at checkout' => 'Log ind ved kassen','Enable log-in during checkout' => 'Aktivér login ved kassen','Show a link for returning customers to log in from the checkout page.' => 'Vis et link på kassesiden, hvor tilbagevendende kunder kan logge ind.','Account creation' => 'Oprettelse af konto','Allow customers to create an account during checkout' => 'Giv kunderne mulighed for at oprette en konto under betalingsprocessen','Customers can create an account before placing their order.' => 'Kunderne kan oprette en konto, inden de afgiver deres ordre.','Allow customers to create an account from the My account page' => 'Giv kunderne mulighed for at oprette en konto fra siden »Min konto«','Customers can register a new account from the My account page.' => 'Kunder kan oprette en ny konto fra siden »Min konto«.','Username' => 'Brugernavn','Generate from customer\'s name' => 'Generer ud fra kundens navn','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Anbefales</strong>, så kunderne ikke bliver bedt om at vælge et brugernavn ved kassen, hvilket kan sænke konverteringsraten.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Et brugernavn genereres ud fra kundens navn eller ud fra e-mailadressen, hvis navnet ikke kan bruges.','Password' => 'Adgangskode','Send password setup link' => 'Send link til opsætning af adgangskode','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Anbefales</strong>, så kunderne ikke bliver bedt om at angive en adgangskode ved kassen, hvilket kan medføre lavere konverteringsrater.','Customers receive an email to create their password securely.' => 'Kunderne modtager en e-mail, hvor de kan oprette deres adgangskode på en sikker måde.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Giv registrerede kunder mulighed for at gennemføre købet uden at logge ind, og knyt ordren til deres eksisterende konto, når kontaktoplysningerne stemmer overens.','Existing account message' => 'Meddelelse om eksisterende konto','Let customers create an account after placing their order, from the thank you page.' => 'Giv kunderne mulighed for at oprette en konto efter at have afgivet deres ordre, direkte fra takkesiden.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Indstillingerne i dette afsnit er tilgængelige, når gæstekøb og kontosammenkobling er aktiveret. Aktiver begge ovenstående funktioner for at konfigurere udskudt kontooprettelse.','Enable delayed account creation' => 'Aktivér forsinket kontooprettelse','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Aktivér forsinket kontooprettelse, når både gæstekøb og kontosammenkobling er aktiveret.','Section position' => 'Afsnitsplacering','Before customer details section' => 'Før afsnittet om kundeoplysninger','After customer details section' => 'Efter afsnittet om kundeoplysninger','Account creation benefits' => 'Fordele ved at oprette en konto','Leaving the field empty will display the default text.' => 'Hvis feltet efterlades tomt, vises standardteksten.','Inline buttons' => 'Inline-knapper','Required fields' => 'Obligatoriske felter','Enable gift message fields at checkout' => 'Aktivér felter til gavebeskeder ved kassen','Expanded gift message' => 'Udvidet gavebesked','Display gift message field always expanded' => 'Feltet til gavebesked skal altid være udvidet','Gift message in order details' => 'Gavebesked i ordreoplysningerne','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Der er i øjeblikket ingen integrationer tilgængelige i dette afsnit. Indstillingerne for de enkelte plugins og temaer vises først her, når det pågældende plugin eller tema er aktiveret.','Phone fields' => 'Telefonfelter','Field visibility' => 'Synlighed i marken','Field position' => 'Feltposition','Phone country code & validation' => 'Landekode for telefonnumre og validering','Country' => 'Land','Enable country on phone fields' => 'Aktivér land i telefonfelterne','Filter countries for shipping or billing' => 'Filtrer lande efter levering eller fakturering','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Begræns landevælgeren i hvert telefonnummerfelt til de lande, der er tilladt til forsendelse eller fakturering i din butik.','Validation' => 'Validering','Enable simple validation based on country rules' => 'Aktivér enkel validering baseret på landespecifikke regler','Checks that the phone number is valid for the selected country, including country code and length.' => 'Kontrollerer, om telefonnummeret er gyldigt for det valgte land, herunder landekode og antal cifre.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Der foretages en strengere kontrol af, om nummeret er et gyldigt mobil-, fastnet- eller andet godkendt nummer for det valgte land. Dette kan medføre, at nogle gyldige numre afvises.','Validation types' => 'Valideringstyper','Placeholders' => 'Pladsholdere','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Der er ingen licensnøgler, der skal administreres i øjeblikket. Licensnøglerne vises her, når et licenseret Fluid Checkout-plugin eller -tilføjelsesprogram er aktivt.','Default delivery type' => 'Standardleveringsform','Choose which delivery type will be selected by default.' => 'Vælg, hvilken leveringsform der skal vælges som standard.','Shipping zone fields' => 'Felter for forsendelseszoner','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Vælg, hvilke felter der skal vises for filterfelterne for forsendelseszonen »Lokal afhentning«. Lad feltet være tomt for at vise alle tilgængelige muligheder.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Disse felter vises som et filter for leveringsmetoderne ved lokal afhentning. Nogle felter kan stadig blive vist ved kassen, selvom de ikke er valgt her, hvis kompatible plugins kræver dem for at fungere korrekt.','Order shipping address' => 'Leveringsadresse for bestillingen','Order pay page optimization' => 'Optimering af betalingssiden ved bestilling','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Giv ubetalte ordrer det samme overskuelige og konverteringsorienterede layout som kassen.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimer layoutet på betalingssiden for ordrer, hvor betalingen endnu ikke er gennemført.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Sørg for, at betalingsoplevelsen stemmer overens med din kasse, så købsforløbet bliver ensartet.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Indsæt tillidssymboler og mærker de steder, hvor kunderne har brug for at blive beroliget, inden de betaler.','Thank you page optimization' => 'Optimering af takkesiden','Make the thank you page and order details clearer for customers after they buy.' => 'Gør takkesiden og ordredetaljerne mere overskuelige for kunderne, når de har købt noget.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimer takkesiden og oplysningerne om ordrer på kontoen med et mere overskueligt layout.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Vis status for ordrens forløb, handlinger, downloads og noter, hvor det er relevant.','Customize order details sections on email notifications.' => 'Tilpas afsnittene med ordreoplysninger i e-mail-beskederne.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Indsæt tillidssymboler og mærker de steder, hvor kunderne har brug for tryghed efter købet.','Email notifications' => 'E-mail-beskeder','Enable thank you page and order details optimizations to see more options' => 'Aktivér optimeringer af takkesiden og ordredetaljerne for at få flere muligheder','Use wide layout on thank you page' => 'Brug et bredt layout på takkesiden','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Disse indstillinger har indflydelse på takkesiden, visningen af ordreoplysninger på kontosiderne og i e-mail-beskeder.','Save settings' => 'Gem indstillinger','Docs' => 'Dokumenter','Cart' => 'Indkøbskurv','Thank you' => 'Tak','Address autocomplete' => 'Automatisk udfyldning af adresse','Trust badges' => 'Tillidsmærker','You do not have permission to save these settings.' => 'Du har ikke tilladelse til at gemme disse indstillinger.','Invalid save request.' => 'Ugyldig anmodning om lagring.','Your settings have been saved.' => 'Dine indstillinger er blevet gemt.','Saving...' => 'Gemmer...','Settings could not be saved. Please try again.' => 'Indstillingerne kunne ikke gemmes. Prøv igen.','Dismiss notice' => 'Luk meddelelsen','Open settings menu' => 'Åbn indstillingsmenuen','Close settings menu' => 'Luk indstillingsmenuen','Preview' => 'Forhåndsvisning','Expand preview' => 'Udvid forhåndsvisning','Collapse preview' => 'Skjul forhåndsvisning','Show header and footer' => 'Vis sidehoved og sidefod','Hide header and footer' => 'Skjul sidehoved og sidefod','Page preview' => 'Sidevisning','Preview viewport' => 'Visningsområde til forhåndsvisning','Tablet' => 'Tablet','Desktop' => 'Skrivebord','Preview width' => 'Bredde på forhåndsvisning','Decrease width' => 'Formindsk bredden','Preview width in pixels' => 'Visningsbredde i pixels','Increase width' => 'Forøg bredden','Preview as' => 'Vis som','Guest' => 'Gæst','Logged in' => 'Logget ind','Preview page' => 'Forhåndsvisningsside','Expand preview for a closer look' => 'Udvid forhåndsvisningen for at se nærmere','Available with %s.' => 'Fås med %s.','Turn them on' => 'Tænd for dem','Optimizations for this page are turned off. %s to preview the page.' => 'Optimeringerne for denne side er deaktiveret. %s for at få et eksempel på siden.','%s preview' => '%s forhåndsvisning','Isolated session · nothing is saved' => 'Isoleret session · intet gemmes','Usage tracking' => 'Sporing af brug','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Send rapporter om webstedsmiljøet, der ikke indeholder følsomme oplysninger, for at hjælpe Fluid Checkout med at forbedre kompatibiliteten. Rapporterne sendes først, når denne funktion er aktiveret i indstillingerne nedenfor.','Send usage tracking reports to Fluid Checkout' => 'Send rapporter om brugsstatistik til Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Disse rapporter hjælper os med at forbedre kompatibiliteten og supporten til dit websted og sendes ugentligt, når funktionen er aktiveret.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Rapporterne indeholder ingen kundeoplysninger, administratoroplysninger eller andre følsomme data.','Basic environment info' => 'Grundlæggende oplysninger om miljøet','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Data om WordPress, PHP, WooCommerce, temaer og plugins. Medtages altid, når rapportering er aktiveret. Hjælper os med at forstå det miljø, dit websted kører i.','Plugin settings' => 'Indstillinger for plugin','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Sender indstillingerne for Fluid Checkout-pluginet for at lette behandlingen af supportanmodninger og hjælpe os med at forstå, hvordan du bruger vores plugins.','Coming soon' => 'Kommer snart','Sales metrics' => 'Salgsmålinger','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Antal månedlige ordrer og det samlede salg i det år, der gik forud for installationen af Fluid Checkout, frem til i dag. Det hjælper os med at forstå, om I tjener flere penge, når vores plugins er installeret. Der sendes aldrig kunde- eller brugerdata.','Utilities' => 'Forsyningstjenester','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Brug <code>TomSelect</code>-dropdown-komponenter i stedet for <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect er en enklere dropdown-komponent, der er mindre fejlbehæftet end Select2, men som samtidig tilbyder den samme funktionalitet.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Indstiller skriftstørrelsen i formularfelterne til 16px på sider, der er optimeret af dette plugin, for at undgå, at der automatisk zoomes ind, når man interagerer med formularfelterne på små enheder.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari og andre browsere kan automatisk zoome ind på mobile enheder for at gøre teksten lettere at læse, når skriftstørrelsen er mindre end 16px.','Enable script processing tracking on the browser console.' => 'Aktivér sporing af scriptbehandling i browserkonsollen.','Unminified assets' => 'Ikke-minificerede ressourcer','Google Maps scripts' => 'Google Maps-scripts','Do not remove duplicate Google Maps scripts' => 'Du må ikke fjerne dublerede Google Maps-scripts','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Når denne indstilling er aktiveret, fjernes duplikerede Google Maps-scripts IKKE, hvilket kan medføre fejl og ydeevneproblemer. Brug kun denne indstilling i forbindelse med fejlfinding.','Widget areas' => 'Widgetområder','Last step on mobile' => 'Sidste trin på mobilen','Display widgets only at last step on mobile' => 'Vis kun widgets i det sidste trin på mobilen','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Vis widgets med tillidsmærker for kassen kun, når man ser det sidste trin i kassen på mobile enheder','Standard' => 'Standard','VAT number field' => 'Feltet til momsnummer','Add a VAT number field to the billing form.' => 'Tilføj et felt til momsnummer på faktureringsformularen.','Field label' => 'Feltbetegnelse','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Indstil etiketten for feltet »Momsnummer« (dvs. »Momsnummer«). På flersprogede hjemmesider er det bedst at lade dette felt stå tomt og oversætte den oprindelige tekststreng.','VAT Number' => 'Momsnummer','EU-VAT' => 'EU-moms','Enable the VAT number field to see more options' => 'Aktivér feltet til momsnummer for at få flere valgmuligheder','VAT validation' => 'Momsvalidering','Validate VAT number field for EU-VAT during checkout' => 'Valider feltet for EU-momsnummer ved kassen','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Kontrollerer, om det angivne momsnummer er et gyldigt momsnummer, der er registreret i den europæiske VIES-database (VAT Information Exchange System).','Shop VAT number' => 'Butikkens momsnummer','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Butikkens momsnummer, der bruges til at anmode om EU-momsvalidering og er trykt på fakturaerne. <br><strong>Vi anbefaler på det kraftigste, at du tilføjer dit butiks momsnummer</strong>, da resultaterne af VIES-forespørgslen ellers muligvis ikke er gyldige til regnskabsmæssige formål. <br>F.eks.: <code>ATU99999999</code> eller <code>EE999999999</code>.','Reverse charge' => 'Omvendt afgiftspligt','Apply reverse charge mechanism' => 'Anvend ordningen med omvendt afgiftspligt','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Indstil skattesatsen til nul, og vis »Reverse charge« på fakturaer, når kundens momsnummer er gyldigt. Afhængigt af butikkens land kan det være nødvendigt at anvende en anden tekst for »Reverse charge«.','Same country' => 'Samme land','Apply reverse charge mechanism for transactions in the shop country:' => 'Anvend ordningen med omvendt afgiftspligt for transaktioner i det land, hvor butikken er beliggende:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Gør det muligt at anvende ordningen med omvendt afgiftspligt for transaktioner mellem virksomheder i samme land som butikken.','Reverse charge exceptions' => 'Undtagelser fra reverse charge-ordningen','Select additional countries to skip applying the reverse charge mechanism.' => 'Vælg yderligere lande, hvor ordningen med omvendt afgiftspligt ikke skal finde anvendelse.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Der opkræves moms på ordrer fra disse lande, selvom der angives et gyldigt momsnummer.','Reverse charge label on invoices' => 'Mærkat om omvendt afgiftspligt på fakturaer','Set the label of "reverse charge" on the checkout page and order details.' => 'Angiv betegnelsen »reverse charge« på betalingssiden og i ordreoplysningerne.','Reverse charge text on invoices' => 'Tekst om omvendt afgiftspligt på fakturaer','Set the label of "reverse charge" text on invoices.' => 'Indstil etiketten for teksten »reverse charge« på fakturaerne.','Tax to be paid on reverse charge basis' => 'Skatten skal betales efter reverse charge-princippet','Company name' => 'Firmanavn','Autocomplete company name from VAT number' => 'Automatisk udfyldning af firmanavn ud fra momsnummer','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Udfyld navnet på den fakturerende virksomhed på baggrund af det gyldige momsnummer, som kunden har opgivet.','Company name editing' => 'Redigering af firmanavn','Allow editing of auto-filled company name' => 'Tillad redigering af automatisk udfyldt firmanavn','When enabled, customers can change the company name associated with the provided VAT number.' => 'Når denne funktion er aktiveret, kan kunderne ændre det firmanavn, der er knyttet til det angivne momsnummer.','EU-VAT for digital goods' => 'EU-moms på digitale varer','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Fra den 1. januar 2015 er der indført ændringer i EU’s momsregler vedrørende digitale varer, som udelukkende vedrører B2C-transaktioner. Momsen på digitale varer skal beregnes ud fra kundens beliggenhed, og der skal indsamles dokumentation herfor (IP-adresse og faktureringsadresse).','Tax classes for digital goods' => 'Skatteklasser for digitale varer','Select some tax classes' => 'Vælg nogle skatteklasser','Location evidence' => 'Bevis for placering','Collect customer\'s location evidence' => 'Indsamle dokumentation for kundens opholdssted','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Gemmer IP-adressen og sammenligner den med kundens faktureringsadresse. Kunden skal bekræfte sin faktureringsadresse ved at markere et afkrydsningsfelt på betalingssiden, hvis landet i faktureringsadressen og IP-adressen ikke stemmer overens.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Denne indstilling administreres i Fluid Checkout. <a href="%s">Du kan ændre den under indstillingerne for kundekonti</a>.','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Denne indstilling administreres i Fluid Checkout. Du kan ændre den under Fluid Checkout > Kundekonti.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Denne indstilling administreres i Fluid Checkout. Leveringsadressen er altid indstillet til »Brug kundens leveringsadresse som standard«, når Fluid Checkout er aktiveret. Kunderne kan stadig angive forskellige leverings- og faktureringsadresser under betalingsprocessen.<br><br>Der findes en indstilling i <a href="%s">Fluid Checkout-indstillingerne</a>, hvor man kan angive, at standardfaktureringsadressen skal være den samme som leveringsadressen.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Denne indstilling administreres i Fluid Checkout. Leveringsadressen er altid indstillet til »Standard til kundens leveringsadresse«, når Fluid Checkout er aktiveret. Kunderne kan stadig angive forskellige leverings- og faktureringsadresser under betalingsprocessen.<br><br>Der findes en indstilling, hvor du kan angive, at standardfaktureringsadressen skal være den samme som leveringsadressen, under WooCommerce > Indstillinger > Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Disse indstillinger er blevet flyttet til WP Admin > Fluid Checkout > Indstillinger.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Fanen »WooCommerce-indstillinger« er udfaset og vil blive fjernet i Fluid Checkout 6.0.','Go to settings page' => 'Gå til indstillingssiden','Hide this tab permanently' => 'Skjul denne fane permanent','Site report preview' => 'Forhåndsvisning af anlægsrapport','This is the data that would be included in the next site environment report based on your current settings.' => 'Dette er de data, der vil indgå i den næste rapport om miljøforholdene på anlægget, baseret på dine nuværende indstillinger.','Loading report preview...' => 'Indlæser forhåndsvisning af rapporten...','Could not load the site report preview. Try again.' => 'Det var ikke muligt at indlæse forhåndsvisningen af webstedsrapporten. Prøv igen.','Could not send the site report. Try again.' => 'Det var ikke muligt at sende rapporten om webstedet. Prøv igen.','Site report sent successfully.' => 'Webstedsrapporten er sendt.','Enable and send now' => 'Aktivér og send nu','Close' => 'Luk','A site report request is already in progress. Try again in a moment.' => 'Der er allerede iværksat en anmodning om en lokalitetsrapport. Prøv igen om et øjeblik.','Site environment reporting is disabled.' => 'Rapportering af webstedsmiljøet er deaktiveret.','No site report data is available to send.' => 'Der er ingen data fra lokalitetsrapporter til rådighed, der kan sendes.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Dette webstedsdomæne kan ikke sende miljørapporter (lokale domæner og udviklingsdomæner er undtaget).','A site report was sent recently. Try again later.' => 'Der blev for nylig sendt en rapport om anlægget. Prøv igen senere.','The site report could not be sent. Try again later.' => 'Det var ikke muligt at sende rapporten om stedet. Prøv igen senere.','Site environment reporting is not available.' => 'Der foreligger ingen rapportering om miljøforholdene på anlægsstedet.','No site report data is available for the selected settings.' => 'Der findes ingen data fra lokalitetsrapporter for de valgte indstillinger.','You are not allowed to manage site reports.' => 'Du har ikke tilladelse til at administrere webstedsrapporter.','PRO feature' => 'PRO-funktion','Other plugins' => 'Andre plugins','Get only this add-on &mdash; %s' => 'Køb kun dette tillægsprogram — %s','Install add-on' => 'Installer tilføjelsesprogram','Upgrade to PRO &mdash; %s' => 'Opgrader til PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Få %2$s</a> for at låse disse muligheder op.','Add-on' => 'Tilføjelse','View documentation' => 'Se dokumentationen','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Anmodninger kræver, at brugeren er logget ind på WordPress. Udelad user_id for at bruge den aktuelle brugers data, eller angiv user_id for at målrette mod en anden konto, når den, der foretager anmodningen, har ret til at redigere den pågældende bruger (rettigheden edit_user). Uautoriserede anmodninger returnerer fc_api_forbidden. Et ugyldigt user_id returnerer fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 med { "data": { ... } }, når handleren returnerer en nyttelast.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 med { "success": true }, når der ikke er nogen datadel (f.eks. DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Fejl returnerer en WordPress REST-fejl i JSON-format fra WP_Error (kode, besked, data.status). Wire-koder bruger præfikset fc_api_*.','Forbidden access.' => 'Adgang forbudt.','Target user was not found.' => 'Den pågældende bruger blev ikke fundet.','This feature is not available.' => 'Denne funktion er ikke tilgængelig.','A required address field is missing.' => 'Der mangler et obligatorisk adressefelt.','Postcode or ZIP is invalid.' => 'Postnummeret er ugyldigt.','Phone number is invalid.' => 'Telefonnummeret er ugyldigt.','State or county is invalid.' => 'Staten eller amtet er ugyldigt.','Country is invalid or has no address fields.' => 'Landet er ugyldigt, eller der er ingen adressefelter.','The request could not be processed.' => 'Anmodningen kunne ikke behandles.','Back to previous step' => 'Tilbage til forrige trin','Skip to settings' => 'Gå direkte til indstillingerne','Start over and return to the first guided setup step' => 'Start forfra og vend tilbage til det første trin i den guidede opsætning','Start over' => 'Start forfra','Please complete all sub-steps before continuing.' => 'Udfyld venligst alle deltrin, før du fortsætter.','Expand' => 'Udvid','Collapse' => 'Skjul','Skip' => 'Spring over','Mark as complete' => 'Markér som afsluttet','Mark as incomplete' => 'Markér som ufuldstændig','View full-size image: %s' => 'Se billedet i fuld størrelse: %s','Full-size setup guide image' => 'Billede af opsætningsvejledningen i fuld størrelse','Close image' => 'Luk billedet','Fluid Checkout Guided Setup' => 'Vejledning til opsætning af væskekontrol','Welcome' => 'Velkommen','Explore your checkout' => 'Se nærmere på din kasse','All set' => 'Så er alt klar','You do not have permission to access this page.' => 'Du har ikke adgang til denne side.','Go to step %1$d: %2$s' => 'Gå til trin %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Denne vejledning hjælper dig med at blive fortrolig med Fluid Checkout. Trinene nedenfor er foreløbig blot pladsholdere.','Continue to the next step when you are ready.' => 'Gå videre til næste trin, når du er klar.','Open your store checkout to see Fluid Checkout in action.' => 'Åbn kassen i din butik for at se Fluid Checkout i praksis.','View checkout page' => 'Gå til betalingssiden','You can return to Fluid Checkout settings to continue configuring your store.' => 'Du kan vende tilbage til indstillingerne for Fluid Checkout for at fortsætte med at konfigurere din butik.','Review checkout and cart settings' => 'Gennemgå indstillingerne for kassen og indkøbskurven','Explore add-ons from the dashboard' => 'Udforsk tilføjelsesprogrammer fra kontrolpanelet','Finish & go to settings' => 'Afslut og gå til indstillinger','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Opdater synlighedsindstillingen for feltet »Faktureringsnummer« fra den gamle værdi, så den stemmer overens med WooCommerce-konventionerne.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Opdater synlighedsindstillingen for feltet »Forsendelsestelefonnummer« fra den gamle værdi, så den stemmer overens med WooCommerce-konventionerne.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Kopier indstillingen for baggrundsfarven i ordresammendraget til den nye indstilling for baggrundsfarven i den sekundære kolonne i »Split«-designet.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Funktionen »Udvidet valg af felter« er altid deaktiveret, når man bruger Biteship-pluginet.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Placeringen af ordreafgivelsesknappen er altid indstillet til »Under ordreoversigten«, når man bruger German Market. Dette plugin kræver, at ordreafgivelsesknappen og de lovmæssige afkrydsningsfelter vises under ordreoversigten.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Placeringen af bestillingsknappen er altid indstillet til »Under ordresammendraget«, når man bruger Germanized til WooCommerce. Dette plugin kræver, at bestillingsknappen og de juridiske afkrydsningsfelter vises under ordresammendraget.','Edit pickup locations' => 'Rediger afhentningssteder','Use local pickup label from WooCommerce settings' => 'Brug et label til lokal afhentning fra WooCommerce-indstillingerne','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Når denne indstilling er aktiveret, svarer betegnelsen for afhentningsmuligheden ved kassen til titlen fra indstillingerne for afhentningssteder i WooCommerce. Når indstillingen er deaktiveret, bruger betegnelsen den oversættelige tekst »Lokal afhentning« fra Fluid Checkout.','Button label for applying coupon codesApply' => 'Ansøg','Checkout step titleContact' => 'Kontakt','Checkout step titleShipping' => 'Forsendelse','Checkout step titleBilling' => 'Fakturering','Checkout step titlePayment' => 'Betaling','Checkout substep change link labelChange' => 'Forandring','Checkout substep save link labelSave changes' => 'Gem ændringer','Substep review textNone.' => 'Ingen.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Intet billede valgt.','Settings sectionCart' => 'Vogn','Settings sectionOrder pay' => 'Bestil løn','Settings sectionThank you' => 'Tak skal du have','Settings section titleIntegrations' => 'Integrationer','Settings section titleLicense keys' => 'Licensnøgler','Captcha positionBefore place order section' => 'Før du bestiller sektionen','Captcha positionBefore place order button' => 'Før bestillingsknappen','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Luk','Log in link label at checkout contact stepLog in' => 'Log ind','Log in separator label at for when guest checkout is disabledOr continue below' => 'Eller fortsæt nedenfor','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Eller fortsæt som gæst','Clear image selection on admin pages.Remove image' => 'Fjern billede','shipping packagesShipping %d' => 'Forsendelse %d','shipping packagesShipping' => 'Forsendelse','Used as fallback for "Proceed to next step" button labelnext step' => 'næste skridt','Substep review checkbox valueYes' => 'Ja','Substep review checkbox line%1$